import numpy as np, os, time
from math import sqrt
try:
    from scipy.optimize import minimize
    SCIPY_AVAILABLE = True
except Exception:
    SCIPY_AVAILABLE = False

N = 32
SHRINK = 1.0 - 1e-12
IMPROVE_EPS = 1e-8
SLACK_REQ = 1e-10

# ---------------- Geometry ----------------
def _pairwise_distances(C: np.ndarray) -> np.ndarray:
    diff = C[:, None, :] - C[None, :, :]
    d2 = np.sum(diff * diff, axis=-1)
    np.fill_diagonal(d2, 0.0)
    d = np.sqrt(d2, out=np.zeros_like(d2), where=(d2 > 0))
    return d

def _boundary_margins(C: np.ndarray) -> np.ndarray:
    x = C[:, 0]; y = C[:, 1]
    return np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))

def _min_slack(C: np.ndarray, r: np.ndarray) -> float:
    # Evaluate smallest slack among all constraints
    x = C[:, 0]; y = C[:, 1]
    sl = np.min(x - r)
    sr = np.min((1.0 - x) - r)
    sd = np.min(y - r)
    su = np.min((1.0 - y) - r)
    D = _pairwise_distances(C)
    Rsum = r[:, None] + r[None, :]
    np.fill_diagonal(D, np.inf)
    pair_sl = np.min(D - Rsum)
    return float(min(sl, sr, sd, su, pair_sl))

def _clip_to_box(C: np.ndarray, margin: float = 1e-4) -> np.ndarray:
    return np.clip(C, margin, 1.0 - margin)

# ---------------- Seeds ----------------
def _load_artifact():
    try:
        data = np.load('storage/verity/sumr32_best.npz')
        C = data['centers']; r = data['radii']; obj = float(data.get('obj', np.sum(r)))
        if C.shape == (N, 2) and r.shape == (N,):
            return C.copy(), r.copy(), obj
    except Exception:
        pass
    return None

def _rotated_hex_seed(n: int, angle_deg: float = 13.5, spacing: float = 0.17, margin: float = 0.02) -> np.ndarray:
    theta = np.deg2rad(angle_deg)
    R = np.array([[np.cos(theta), -np.sin(theta)],[np.sin(theta), np.cos(theta)]], dtype=float)
    xs = np.arange(-6, 7) * spacing
    ys = np.arange(-6, 7) * (spacing * sqrt(3)/2.0)
    pts = []
    for j, y in enumerate(ys):
        xoff = (0.5 * spacing) if (j % 2) else 0.0
        for x in xs:
            p = (R @ np.array([x + xoff, y])) + np.array([0.5, 0.5])
            if margin <= p[0] <= 1.0 - margin and margin <= p[1] <= 1.0 - margin:
                pts.append(p)
    pts = np.array(pts, dtype=float)
    rng = np.random.default_rng(123)
    chosen = [pts[rng.integers(0, len(pts))]]
    for _ in range(1, n):
        d = np.sqrt(np.sum((pts[:, None, :] - np.array(chosen)[None, :, :])**2, axis=-1))
        idx = int(np.argmax(np.min(d, axis=1)))
        chosen.append(pts[idx])
    return np.array(chosen, dtype=float)

def _farthest_sampling(n: int, rng, margin=0.02, candidates=350) -> np.ndarray:
    pts = [np.array([0.5, 0.5], dtype=float)]
    for _ in range(1, n):
        cand = rng.uniform(margin, 1.0 - margin, size=(candidates, 2))
        exist = np.array(pts)
        d = np.sqrt(np.sum((cand[:, None, :] - exist[None, :, :])**2, axis=-1))
        min_to_pts = np.min(d, axis=1)
        b = np.minimum(np.minimum(cand[:, 0], 1.0 - cand[:, 0]), np.minimum(cand[:, 1], 1.0 - cand[:, 1]))
        score = np.minimum(min_to_pts, 2.0 * b)
        pts.append(cand[int(np.argmax(score))])
    return np.array(pts, dtype=float)

# ---------------- SLSQP (joint centers + radii) ----------------
def _pack_z(C: np.ndarray, r: np.ndarray) -> np.ndarray:
    return np.concatenate([C.reshape(-1), r], axis=0)

def _unpack_z(z: np.ndarray) -> tuple:
    C = z[:2*N].reshape(N, 2)
    r = z[2*N:]
    return C, r

def _objective(z: np.ndarray) -> float:
    _, r = _unpack_z(z)
    return -float(np.sum(r))  # maximize sum r

def _constraints():
    cons = []
    # Boundary inequalities: cxi - r_i >= 0, 1 - cxi - r_i >= 0, etc.
    def make_bound_fun(idx, axis, sign):
        # sign +1: c - r; sign -1: 1 - c - r
        def fun(z):
            C, r = _unpack_z(z)
            c = C[idx, axis]
            return (c - r[idx]) if sign == +1 else (1.0 - c - r[idx])
        return fun
    for i in range(N):
        cons.append({'type':'ineq','fun': make_bound_fun(i, 0, +1)})  # left
        cons.append({'type':'ineq','fun': make_bound_fun(i, 0, -1)})  # right
        cons.append({'type':'ineq','fun': make_bound_fun(i, 1, +1)})  # down
        cons.append({'type':'ineq','fun': make_bound_fun(i, 1, -1)})  # up
        # positivity r_i >= 0
        cons.append({'type':'ineq','fun': (lambda idx=i: (lambda z: _unpack_z(z)[1][idx]))()})
    # Pairwise: ||ci - cj|| - (ri + rj) >= 0
    def make_pair_fun(i, j):
        def fun(z):
            C, r = _unpack_z(z)
            d = np.linalg.norm(C[i] - C[j])
            return d - (r[i] + r[j])
        return fun
    for i in range(N):
        for j in range(i+1, N):
            cons.append({'type':'ineq','fun': make_pair_fun(i, j)})
    return cons

def _bounds():
    b = []
    # Centers in [0,1], Radii in [0, 0.5] (safe upper bound)
    for _ in range(2*N):
        b.append((0.0, 1.0))
    for _ in range(N):
        b.append((0.0, 0.5))
    return b

def _slsqp_optimize(C0: np.ndarray, r0: np.ndarray, time_left: float):
    if not SCIPY_AVAILABLE or time_left < 1.0:
        return C0, r0, float(np.sum(r0)), False
    z0 = _pack_z(C0, r0)
    res = minimize(_objective, z0, method='SLSQP',
                   bounds=_bounds(), constraints=_constraints(),
                   options={'maxiter': 200, 'ftol': 1e-12, 'disp': False})
    if not res.success:
        return C0, r0, float(np.sum(r0)), False
    C, r = _unpack_z(res.x)
    # Ensure numerical clipping inside box (feasible region guarded by constraints, but add tiny clip)
    C = _clip_to_box(C, 1e-10)
    return C, np.maximum(r, 0.0), float(np.sum(r)), True

# ---------------- Fallback / Return (immutable loader v4) ----------------
def _fallback():
    xs = (2*np.arange(6) + 1) / 12.0
    ys = (2*np.arange(6) + 1) / 12.0
    centers = []
    for j, y in enumerate(ys):
        for i, x in enumerate(xs):
            if (i, j) in [(0,0), (5,0), (0,5), (5,5)]: continue
            centers.append([x, y])
    centers = np.array(centers, dtype=float)[:N]
    radii = np.full(N, (1.0/12.0) * SHRINK, dtype=float)
    return centers, radii

def _return_loader():
    try:
        data = np.load('storage/verity/sumr32_best.npz')
        C = data['centers']; r = data['radii']
        if C.shape == (N, 2) and r.shape == (N,):
            return C.astype(float), np.maximum(r * SHRINK, 1e-16).astype(float)
    except Exception:
        pass
    return _fallback()

# ---------------- Persist-if-improved ----------------
def _persist_if_improved(Cbest, rbest, objbest, obj0):
    # Evaluate safety on micro-shrunk radii (policy)
    r_safe = rbest * SHRINK
    if objbest > obj0 + IMPROVE_EPS and _min_slack(Cbest, r_safe) >= SLACK_REQ:
        try:
            os.makedirs('storage/verity', exist_ok=True)
            np.savez('storage/verity/sumr32_best.npz', centers=Cbest, radii=rbest, obj=float(np.sum(rbest)))
        except Exception:
            pass

# ---------------- Main ----------------
def construct_packing() -> tuple:
    t0 = time.time()
    time_budget = 12.0  # seconds for offline search; return path remains constant

    rng = np.random.default_rng(2026)
    art = _load_artifact()
    if art is not None:
        C_art, r_art, obj_art = art
    else:
        # initialize from structured seeds
        C_art = _rotated_hex_seed(N)
        r_art = np.full(N, 0.05, dtype=float)
        obj_art = float(np.sum(r_art))

    bestC, bestR, bestObj = C_art.copy(), r_art.copy(), obj_art

    # Build seed list: artifact, rotated hex, farthest sampling
    seeds = [(C_art, r_art)]
    seeds.append((_rotated_hex_seed(N), np.full(N, 0.05, dtype=float)))
    seeds.append((_farthest_sampling(N, rng, margin=0.02, candidates=350), np.full(N, 0.05, dtype=float)))

    # Run a limited SLSQP on each seed within time budget
    if SCIPY_AVAILABLE:
        for (C0, r0) in seeds:
            if time.time() - t0 > time_budget: break
            C0 = _clip_to_box(C0, 1e-4)
            C_opt, r_opt, obj_opt, ok = _slsqp_optimize(C0, r0, time_budget - (time.time() - t0))
            if ok and obj_opt > bestObj + 1e-10:
                bestC, bestR, bestObj = C_opt, r_opt, obj_opt

    # Persist only if safely better than artifact under policy checks
    if art is not None:
        _persist_if_improved(bestC, bestR, bestObj, obj_art)
    else:
        _persist_if_improved(bestC, bestR, bestObj, obj_art)

    # Return immutable loader result (centers unchanged; radii micro-shrunk)
    return _return_loader()
